"""Generate release evidence from actual saved final-run records."""
from pathlib import Path
import json,hashlib,re
root=Path(__file__).resolve().parents[1];b=root/'build'
gate=json.loads((b/'release09-results.json').read_text());rows=json.loads((b/'performance09.json').read_text())
assert len(gate['results'])==33 and all(r['exit_code']==0 for r in gate['results'])
assert gate['iso_sha256']==hashlib.sha256((b/'slopix.iso').read_bytes()).hexdigest()
assert len(rows)==25
text=['# Slopix 0.9 final regression results','',f"Tested ISO SHA-256: `{gate['iso_sha256']}`.",'','33 command groups passed on this unchanged ISO. The host group includes Rust','unit/ABI tests and C ASan/UBSan renderer, framebuffer, runtime, DOOM compatibility,','PCM/SFX, preferences, frame statistics, VM/ELF, internal interfaces and FileSlop/','clipboard tests. Host tests do not establish CPU privilege isolation.','', '| Check | Result | Seconds |','|---|---|---:|']
for r in gate['results']:text.append('| '+r['command'][-1]+' | PASS | '+str(round(r['seconds'],2))+' |')
text+=['','New storage tests compare fragmented multi-megabyte data after range append,','copy/rename and cold boot, including independent mtools and fsck validation.','The streaming READ.ELF runs at CPL3 with bounded memory; new heap and lifecycle','tests exercise real PMM/SB16 service and repeated fresh DOOM sessions.','','The userspace guest test executes real disk-loaded ELF64 code at CPL3, normal','exit, bad pointers, UD/GP/PF/divide faults, kernel-access protection, RX/NX, stack','guard, per-process SSE state, sleep, timer preemption, kill and reclamation.','Free physical-page counts return to baseline; DOOM and audio continue.','', 'The supplied disk and ELF are also tested together. FileSlop tests exercise','real creation, text viewing, cancel/confirmed removal, clipboard in both','directions, cold persistence and independent fsck. Host injection covers its','read-only/full/I/O and capacity limits. The existing storage suites separately','test actual failed writes, full images, degraded volumes and user-file retention.','', 'Desktop coverage includes new tab dragging/hitboxes, resize, focus, minimize,','maximize/restore, close/reopen, panel hover/auto-hide/top placement, pinboard','drag/keyboard launch, context menu, configuration cold recovery and all six apps','across supported resolutions. Older Dock-specific assertions were replaced by','new panel assertions; model/lifecycle/clipping assertions were retained.','', 'See `build/release09-results.json` and its per-group logs for raw results.','See `PERFORMANCE-0.9.md`, graphical09.log and final09-pa-10000.json/log for','performance and graphical audio evidence. Physical speakers, physical monitor','latency and real hardware remain unverified. Earlier release reports are historical.']
(root/'TEST-RESULTS-0.9.md').write_text('\n'.join(text)+'\n')
text=['# Slopix 0.9 performance measurements','','QEMU TCG, qemu64, PC, 256 MiB, standard VGA, no network; sequential guests.','The matrix uses no display frontend and the silent audio backend for emulated','SB16 workloads. These measurements are framebuffer-submission intervals, not','proof of subjective smoothness or physical presentation latency. Separate SDL/','PulseAudio tests are recorded below and in graphical09.log.','', 'Each matrix phase observes eight seconds. Frame percentiles use the latest','bounded 256-interval kernel ring emitted during that phase (counts are retained','in JSON). They can include phase setup/focus transitions. “1% low” is the inverse','mean of the slowest floor(n/100), minimum one, intervals. FPS is actual timer-','measured submissions. No 60 FPS DOOM target is implied: simulation is ~35 Hz.','', '| Resolution | Workload | FPS | 1% low | p95 ms | p99 ms | Worst ms | CPU % of one core | Enter ms* |','|---|---|---:|---:|---:|---:|---:|---:|---:|']
for r in rows:
 f=r['frames'];text.append('| '+'×'.join(map(str,r['resolution']))+' | '+r['workload']+' | '+f"{f['fps10']/10:.1f} | {f['low1_fps10']/10:.1f} | {f['p95_us']/1000:.2f} | {f['p99_us']/1000:.2f} | {f['max_us']/1000:.2f} | {r['cpu_percent_one_core']:.1f} | {r['enter_serial_ms_including_16ms_driver_delay']:.1f} |")
worst=max(rows,key=lambda r:r['frames']['max_us'])
text+=['',f"Largest matrix gap: {worst['frames']['max_us']/1000:.2f} ms at {worst['resolution'][0]}×{worst['resolution'][1]} ({worst['workload']}). It remains included in the table."]
text+=['','*Enter-to-serial includes the automation driver’s 16 ms key delay and polling;','it is not physical input-to-photon latency. `PERF event_queue` in raw stage','reports measures queued PS/2-byte handling delay inside the kernel. Stage','measurements overlap hierarchically (DOOM contains game/render); do not add all','averages as if independent. CPU comes from the live QEMU process CPU clock.','', 'All 25 phases require zero audio underruns/device faults and working Terminal','input. Audio phases enable SB16. Fire is held during DOOM-focused phases; focus','loss releases it in cube phases, matching normal input routing. “All six” means','all apps open, DOOM brought forward and the cube over it, leaving both visible.','', '## Baseline and bottleneck','','M0-AUDIO-REPORT.md preserves the actual GTK/PulseAudio reproduction: an','instrumented 0.85-era two-block ring stopped after a 56.4 ms service gap. A','four-block ring alone still failed (120.6 ms gap); unconditional cache callbacks','also reduced frame rate. Completion-counter-gated safe points restored ~35 Hz','and zero underruns in the matched accepted run. A memtest stall was separately','reproduced and addressed with bounded main-thread audio service points.','', 'The time between frames includes intentional 35 Hz pacing and shared desktop','work, so the DOOM work label alone is not total frame duration. Resolution','regeneration remains synchronous: the M0 sustained test recorded a 331 ms gap','during mode switches. Do not interpret steady-phase averages as no-transition-','stutter guarantees. Original measured before/after distributions remain in the','M0 report; the redesigned 0.9 desktop is not an otherwise identical baseline.','', '## Graphical and sustained tests','','See build/graphical09.log and build/final09-pa-10000.json/log for the final','SDL/PulseAudio run, actual counter values and frame distributions. The graphical combined phase keeps the cube visibly left of DOOM while firing;', 'all six applications remain open. SDL ran on','a virtual X display with a real PulseAudio server/null sink and monitor capture.','Nonzero PCM reaching that monitor verifies the host audio path; it does not','verify physical speaker quality. See the recorded idle/sustained CPU JSON for','the independent stability phases.']
probe=json.loads((b/'final09-pa-10000.json').read_text())
text+=['','| SDL/PulseAudio phase | FPS | 1% low | p95 ms | p99 ms | Worst ms |','|---|---:|---:|---:|---:|---:|']
for row in probe:
 records=[{k:int(v) for k,v in re.findall(r'(\w+)=(-?\d+)',line)} for line in row['report'].splitlines() if line.startswith('FRAMES ')]
 for f in records:
  app='DOOM' if f['app']==0 else '3D'
  text.append('| '+row['label']+' / '+app+' | '+f"{f['fps10']/10:.1f} | {f['low1_fps10']/10:.1f} | {f['p95_us']/1000:.2f} | {f['p99_us']/1000:.2f} | {f['max_us']/1000:.2f} |")
text+=['','All graphical phases reported zero underruns and zero device faults.','The SDL live-refresh test verifies visible pixel changes without QMP screendump. The combined phase also asserts continuously advancing cube statistics while','DOOM fires. PulseAudio sample count/peak are recorded in graphical09.log.']
stability=json.loads((b/'stability.json').read_text())['0.9']
text+=['',f"Steady idle QEMU CPU: {stability['idle']['percent_one_core']:.2f}% of one core over {stability['idle']['wall_s']:.1f} s.",f"Sustained cube QEMU CPU: {stability['animated']['percent_one_core']:.2f}% over {stability['animated']['wall_s']:.1f} s; host-observed frame counter rate {stability['animated']['host_frame_fps']:.2f} FPS."]
(root/'PERFORMANCE-0.9.md').write_text('\n'.join(text)+'\n')
print('Wrote reports from final gate and 25 actual measurement records')

times=json.loads((b/'storage-stream-command-times.json').read_text())
with (root/'PERFORMANCE-0.9.md').open('a') as out:
 out.write('\n## Synchronous storage operation latency\n\n')
 for row in times:
  if row['command'].startswith(('cp ','append ')):
   out.write('`'+row['command']+'`: '+str(round(row['enter_to_complete_seconds_including_driver_poll']*1000,2))+' ms Enter-to-command-complete, including driver/poll delay.\n\n')
 out.write('These operations continue audio service but do not yield desktop presentation. They are not asynchronous copies.\n')

baseline=json.loads((b/'light-baseline-performance.json').read_text())
with (root/'PERFORMANCE-0.9.md').open('a') as out:
 out.write('\n## Matched Pre-Genesis comparison\n\nBaseline ISO: `'+baseline[0]['iso_sha256']+'`. Same TCG configuration and five workload scripts per resolution, measured at different host times. Host load is not controlled.\n\n')
 out.write('| Resolution | Before mean FPS | After mean FPS | Before lowest1% | After lowest1% | Before worst ms | After worst ms |\n|---|---:|---:|---:|---:|---:|---:|\n')
 for resolution in [(800,600),(1024,600),(1280,800),(1600,900),(1920,1080)]:
  a=[r['frames'] for r in baseline if r['resolution']==list(resolution)]
  c=[r['frames'] for r in rows if r['resolution']==list(resolution)]
  out.write('| '+'x'.join(map(str,resolution))+' | '+f"{sum(v['fps10'] for v in a)/len(a)/10:.2f} | {sum(v['fps10'] for v in c)/len(c)/10:.2f} | {min(v['low1_fps10'] for v in a)/10:.1f} | {min(v['low1_fps10'] for v in c)/10:.1f} | {max(v['max_us'] for v in a)/1000:.2f} | {max(v['max_us'] for v in c)/1000:.2f} |\n")
 out.write('\nMeans average the five phase FPS values; lows/worst retain the most adverse sample across those phases. No physical presentation claim follows.\n')
